function BaseListener.registerCallBack(event, func)
    callbacks[event] = callbacks[event] or {}
    if TableUtil.tableContain(callbacks[event], func) then
        return
    end
    table.insert(callbacks[event], func)
end

function BaseListener.unregisterCallBack(event, func)
    for i, fn in ipairs(callbacks[event] or {}) do
        if fn == func then
            table.remove(callbacks[event], i)
            return
        end
    end
end

