---@private
function BaseListener:destroy()
    self.isDestroyed = true
    callbacks = {}
end

function BaseListener:GetIsDestroyed()
    return self.isDestroyed or false
end

function BaseListener:init()
    self.isDestroyed = false
    CEvents.GameDestroyEvent:unregisterAll()
    CEvents.GameInitEvent:unregisterAll()
    CEvents.GameInitEvent:registerCallBack(self.onGameInit)
    CEvents.GameDestroyEvent:registerCallBack(self.onGameDestroy)
    Root.Instance():setRenderMainScreenSeparate(false)
    Root.Instance():setEnableMergeBlock(false)
end

