    Listener.registerCallBack(CEvents.GameReadyEvent, BaseListener.onGameReady)
    Listener.registerCallBack(CEvents.GameExitEvent, BaseListener.onGameExit)
    Listener.registerCallBack(CEvents.ServerCommonDataEvent, BaseListener.onServerCommonData)
    Listener.registerCallBack(CEvents.GameMainTickEvent, BaseListener.onGameMainTick)
    Listener.registerCallBack(CEvents.HideAllLayoutEvent, BaseListener.onHideAllLayout)
    Listener.registerCallBack(CEvents.RecoverAllLayoutEvent, BaseListener.onRecoverAllLayout)
    Listener.registerCallBack(CEvents.ShowPluginLayoutEvent, BaseListener.onShowPluginLayout)
    Listener.registerCallBack(CEvents.GameActionTriggerEvent, BaseListener.onGameActionTrigger)
    Listener.registerCallBack(CEvents.SpawnEntityEvent, BaseListener.onSpawnEntity)
    Listener.registerCallBack(CEvents.RemoveEntityEvent, BaseListener.onRemoveEntity)
    Listener.registerCallBack(CEvents.OtherPlayerSpawnEvent, BaseListener.onOtherPlayerSpawn)
    Listener.registerCallBack(CEvents.PlayerRebirthEvent, BaseListener.onPlayerRebirth)
    Listener.registerCallBack(CEvents.PlayerLoginEvent, BaseListener.onPlayerLogin)
    Listener.registerCallBack(CEvents.PlayerLogoutEvent, BaseListener.onPlayerLogout)
    Listener.registerCallBack(CEvents.LuaPlayerDeathEvent, BaseListener.onPlayerDeath)
    Listener.registerCallBack(CEvents.GameOverEvent, BaseListener.onGameOver)
    Listener.registerCallBack(CEvents.ShowMainControlEvent, BaseListener.onShowMainControl)
    Listener.registerCallBack(CEvents.HideRechargeEvent, BaseListener.onHideRecharge)
    Listener.registerCallBack(CEvents.HidePluginLayoutEvent, BaseListener.onHidePluginLayout)
    Listener.registerCallBack(CEvents.ShowSettingMenuEvent, BaseListener.onShowSettingMenu)
    Listener.registerCallBack(CEvents.UpdateUserListEvent, BaseListener.onUpdateUserList)
    Listener.registerCallBack(CEvents.FPVCheckEnableEvent, BaseListener.onFPVCheckEnableEvent)
    Listener.registerCallBack(CEvents.PlayFPVActionEvent, BaseListener.onPlayFPVActionEvent)
    Listener.registerCallBack(CEvents.PlayerPlayBaseActionEvent, BaseListener.onPlayerPlayBaseAction)
    Listener.registerCallBack(CEvents.PlayerPlayUpperActionEvent, BaseListener.onPlayerPlayUpperAction)
    Listener.registerCallBack(CEvents.ClickSceneEvent, BaseListener.onClickScene)
    Listener.registerCallBack(CEvents.CheckMoneyEvent, BaseListener.onCheckMoney)
    Listener.registerCallBack(CEvents.ClientCmdEvent, BaseListener.onClientCmd)
    tryCallEvent(CEvents.GameInitEvent)
    WebService:GetUserDetail(Game:getPlatformUserId(), function()
        Events.GetUserDetailFinishEvent:invoke()
    end)

    ClientHelper.putBoolPrefs("ShowUidDetailText", false)
    ClientHelper.putIntPrefs("UidDetailTextOffsetX", -200)
    ClientHelper.putIntPrefs("UidDetailTextOffsetY", -48)
    ClientHelper.putBoolPrefs("ActorDelayUnloadParts", true)
