function BaseListener.onGameLoadMapSuccess(mapPath, rootPath)
    ConfigLoader.setMapPath(mapPath .. '/')
    FileUtil:setMapPath(mapPath)
    FileUtil:setRootPath(rootPath)
    Lang:init()
    GameAnalytics:init()
    Global:loadSetting()
    tryCallEvent(CEvents.GameLoadMapSuccessEvent)
end

function BaseListener.onLuaLoadWorldEnd()
    PlayerManager:createClientPlayer()
    tryCallEvent(CEvents.LuaLoadWorldEndEvent)
end

function BaseListener.onGameReady()
    GameType = CGame.Instance():getGameType()
    BaseMain:setGameType(GameType)
    LogUtil.logInfo("BaseListener.onGameReady() GameType=" .. GameType)
    Game:init()
    GUIManager:init()
    EntityCache:init()
    MaxRecordHelper:init()
    UIHelper.requireGUILayout("GUICustomDialog", true)
    Plugins.LoadAllPlugins()
    Plugins.CallPluginFunc("onGameInit")
    Plugins.CallPluginFunc("onPlayerLogin", PlayerManager:getClientPlayer())
    Plugins.CallPluginFunc("onPlayerReady", PlayerManager:getClientPlayer())
    UIHelper.requireGUILayout("GUIProbabilityDialog", true)
    local customUI = require "engine_client.ui.CCustomGUI"
    customUI:init()
    tryCallEvent(CEvents.GameReadyEvent)
    initCustomDialog("CustomDialog.json")
    UIHelper.requireGUILayout("GUICheckMoneyContent", true)
    initProbabilityDialog("ProbabilityDialog.json")

    require "engine_client.config.SumRechargeConfig"
    require "engine_client.config.GeneralProbabilityConfig"
    SumRechargeConfig:init()

    if not GUIFriendFollow then
        ---游戏覆盖 游戏先声明就不加载引擎的
        ---@type UIFriendFollow
        GUIFriendFollow = UIHelper.newEngineGUILayout("GUIFriendsFollow", "FriendsFollow.json", GUIManager:getMainControl())
    end
    ---@type UIFriendsFollowTip
    GUIFriendsFollowTip = UIHelper.newEngineGUILayout("GUIFriendsFollowTip", "FriendsFollowTip.json")

    if Game:isOpenGM() then
        GMHelper:enableGM()
    end
    if isLocalWin then
        startLuaHotUpdate()
    end
    if isAudioApp then
        ---视频组的包需要隐藏名字
        ClientHelper.putBoolPrefs("RenderHeadText", false)
    end
end

function BaseListener.onGameExit(isNetConnected)
    if isNetConnected then
        local Quality = T(Global, "Quality")
        Quality:performanceReport()
    end
end

function BaseListener.onGameDestroy()
    tryCallEvent(CEvents.GameDestroyEvent)
    if Platform.isWindow() then
        ---@type SharePreferences
        local SharePreferences = T(Global, "SharePreferences")
        SharePreferences:close()
    end
    GUIManager:destroy()
    WebService:destroy()
    BaseListener:destroy()
    LuaTimer:cancelAll()
    PlayerManager:destroy()
    EntityCache:destroy()
    PacketSender:destroy()
    MemoryPool.clearPool()
end

function BaseListener.onServerCommonData(key, data)
    CommonDataEvents:dispatchEvent(key, data)
end

function BaseListener.onGameMainTick(frameTime)
    local renderDt = Blockman.Instance().m_render_dt
    GUIManager:onTick(frameTime, renderDt)
    LuaTimer:onTick(frameTime)
    EntityCache:onTick(frameTime, renderDt)
    UserInfoCache:tryDoRequestCache()
    tryCallEvent(CEvents.GameMainTickEvent, frameTime, renderDt)
end

function BaseListener.onHideAllLayout()
    GUIManager:hideAllLayout()
end

function BaseListener.onRecoverAllLayout()

end

function BaseListener.onShowPluginLayout(name, params)
    local layout = GUIManager:getLayout(name)
    if not layout then
        return
    end
    layout:show(params)
end

function BaseListener.onGameActionTrigger(type, params)
    if type == CDefine.GameActionType.GAME_ACTION_DISABLE_RECHARGE then
        PayHelper.disableRecharge()
    elseif type == CDefine.GameActionType.GAME_ACTION_ACTIVE_DISCONNECT then
        local layout = GUIManager:getLayout("DisconnectMask.json")
        if not layout then
            ---@type UIDisconnectMaskLayout
            layout = UIHelper.newEngineGUILayout("GUIDisconnectMask")
        end
        layout:show(params)
    elseif type == CDefine.GameActionType.GAME_ACTION_ACTIVE_CONNECT then
        local layout = GUIManager:getLayout("DisconnectMask.json")
        if layout then
            layout:hide(true)
        end
    end
    tryCallEvent(CEvents.GameActionTriggerEvent, type, params)
end

function BaseListener.onOtherPlayerSpawn(otherPlayerMP)
    local player = PlayerManager:getPlayerByPlayerMP(otherPlayerMP)
    if not player then
        player = PlayerManager:createOtherPlayer(otherPlayerMP)
        Plugins.CallPluginFunc("onPlayerLogin", player)
    else
        player:onSpawn(otherPlayerMP)
    end
    tryCallEvent(CEvents.OtherPlayerSpawnEvent, player)
end

function BaseListener.onPlayerRebirth(playerSPMP)
    if not PlayerManager:getClientPlayer() then
        PlayerManager:createClientPlayer()
    else
        PlayerManager:getClientPlayer():onSpawn(playerSPMP)
    end
    tryCallEvent(CEvents.PlayerRebirthEvent, PlayerManager:getClientPlayer())
end

function BaseListener.onSpawnEntity(entity, type, properties)
    if not EngineWorld:getWorld() then
        return
    end
    local lEntity = EntityCache:createEntityCache(entity, type, properties)
    tryCallEvent(CEvents.SpawnEntityEvent, lEntity)
end

function BaseListener.onRemoveEntity(entityId)
    EntityCache:removeEntityCache(entityId)
    tryCallEvent(CEvents.RemoveEntityEvent, entityId)
end

local function onPlayerLoginUpdateCache(userId, teamId, personalityItems)
    if userId == Game:getPlatformUserId() then
        local cache = UserInfoCache:GetCache(userId)
        if cache and cache.nickName then
            UserInfoCache:UpdateUserInfos({ { userId = userId, teamId = teamId, } })
            return
        end
    end
    if personalityItems and personalityItems ~= "" then
        personalityItems = json.decode(personalityItems)
    else
        personalityItems = nil
    end
    local user = UserManager.Instance():findUser(userId)
    UserInfoCache:UpdateUserInfos({
        {
            userId = userId,
            teamId = user.teamId,
            nickName = StringUtil.getRealName(user.userName),
            sex = user.sex,
            vip = user.vip,
            friend = user.isFriend,
            picUrl = user.picUrl,
            country = user.country,
            language = user.language,
            isRobot = user.isRobot,
            status = 10, ---在线
            personalityItems = personalityItems
        }
    })
end

function BaseListener.onPlayerLogin(userId, teamId, enterAnnounce, personalityItems)
    onPlayerLoginUpdateCache(userId, teamId, personalityItems)
    --enterAnnounce = [[{"bg":"vip_entergame_008.json", "lang_key":"%s join in the hall handsomely!"}]] -- for test
    Plugins.CallPluginFunc("onUserLogin", userId, enterAnnounce or "")
    t_h_l_len()-- lua anti 
end

function BaseListener.onPlayerLogout(userId)
    local player = PlayerManager:getPlayerByUserId(userId)
    if not player then
        return
    end
    Plugins.CallPluginFunc("onPlayerLogout", player)
    if player.Player then
        player.Player:setActorInvisible(true)
        player.Player:setInvisible(true)
    end
    tryCallEvent(CEvents.PlayerLogoutEvent, player)
    player:onLogout()
    player.Player = nil
    PlayerManager:subPlayer(userId)
end

function BaseListener.onPlayerDeath(userId)
    local player = PlayerManager:getPlayerByUserId(userId)
    if not player then
        return
    end
    if userId == Game:getPlatformUserId() then
        return
    end
    player:onSpawn(nil)
end

function BaseListener.onGameOver(message)
    GUIManager:clearShowQueue()
    GUIManager:hideAllLayout(true)
    ClientHelper.callAppJsonFunction("onGameOver", { message = message })
end

function BaseListener.onShowMainControl()
    GUIManager:showMainControlLayout()
end

function BaseListener.onHideRecharge()
    PayHelper.disableRecharge()
end

function BaseListener.onHidePluginLayout(name)
    local layout = GUIManager:getLayout(name)
    if not layout then
        return
    end
    layout:hide()
end

function BaseListener.onShowSettingMenu()
    if not GUIFriendFollow then
        return false
    end
    if GUIFriendFollow.followerId == nil then
        local callback = callbacks[CEvents.ShowSettingMenuEvent]
        if not callback then
            return true
        end
        return tryCallEvent(CEvents.ShowSettingMenuEvent)
    end
    GUIFriendFollow:onQuit()
    return false
end

function BaseListener.onUpdateUserList(_)
    local userIds = UserManager.Instance():getAllUser()
    for _, userId in pairs(userIds) do
        local user = UserManager.Instance():findUser(userId)
        if user then
            UserInfoCache:UpdateUserInfos({ { userId = userId, friend = user.isFriend, } })
        end
    end
end

