function BaseListener.onPlayerPlayBaseAction(entityPlayer, _, skillProxy)
    local player = PlayerManager:getPlayerByUserId(entityPlayer:getPlatformUserId())
    if not player then
        return
    end
    if player:getBaseAction() then
        skillProxy.value = player:getBaseAction()
    end
end


