    end
    return tryCallEvent(CEvents.ClickSceneEvent)
end

function BaseListener.onCheckMoney(coinId, price)
    local money = PlayerWallet.getMoneyByCoinId(coinId)
    if coinId == CurrencyId.GCube or coinId == CurrencyId.Diamonds then
        money = money + PlayerWallet.getMoneyByCoinId(CurrencyId.GameCashCoupon)
    end
    if money < price then
        return false
    else
        return true
    end
end

